const cfg = {
  url: $env.ODOO_URL,
  db: $env.ODOO_DB,
  user: $env.ODOO_USER,
  key: $env.ODOO_API_KEY,
  publicUrl: $env.ODOO_PUBLIC_URL || $env.ODOO_URL,
};
const rpc = async (service, method, args) => {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `${cfg.url}/jsonrpc`,
    json: true,
    body: { jsonrpc: '2.0', method: 'call', params: { service, method, args } },
  });
  if (res.error) throw new Error(`Odoo: ${res.error.data?.message || res.error.message}`);
  return res.result;
};
const uid = await rpc('common', 'login', [cfg.db, cfg.user, cfg.key]);
if (!uid) throw new Error('Odoo: usuario o API key incorrectos');
const odoo = (model, method, args, kwargs = {}) =>
  rpc('object', 'execute_kw', [cfg.db, uid, cfg.key, model, method, args, kwargs]);

const m = $json;
const remitente = m.from?.value?.[0] || {};
const texto = (m.text || String(m.html || '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' '))
  .replace(/\n{3,}/g, '\n\n')
  .trim()
  .slice(0, 15000);

const tipos = await odoo('crm.service.type', 'search_read', [[]], { fields: ['code', 'name'] });
const productos = await odoo('product.product', 'search_read',
  [[['sale_ok', '=', true], ['is_storable', '=', true]]],
  { fields: ['default_code', 'name'], limit: 500 });

const catalogoTipos = tipos.map((t) => `${t.code}: ${t.name}`).join('\n');
const catalogoProductos = productos.map((p) => `${p.default_code || '-'}: ${p.name}`).join('\n');

const instruccion = `Analiza el correo recibido por el área comercial.
Clasifícalo como "solicitud" si pide un servicio, una cotización o productos; "consulta" si solo pide información general; "otro" en cualquier otro caso (publicidad, notificaciones, proveedores, spam).
Extrae los datos del cliente y de lo que necesita. Si un dato no aparece, devuelve null.
tipo_servicio debe ser uno de estos códigos o null:
${catalogoTipos}
Para cada producto pedido, usa el código del catálogo cuando corresponda y la cantidad como número:
${catalogoProductos}
urgencia: "alta" si pide atención inmediata o en menos de una semana, "media" si da un plazo, "baja" en otro caso.
fecha_deseada en formato YYYY-MM-DD. Fecha del correo: ${m.date || $now.toISODate()}.
resumen: máximo tres oraciones, en español, con lo que el cliente necesita.`;

const correo = `De: ${remitente.name || ''} <${remitente.address || ''}>
Asunto: ${m.subject || ''}

${texto}`;

const tipoServicio = { type: ['string', 'null'] };
if (tipos.length) tipoServicio.enum = [...tipos.map((t) => t.code), null];
const texto_ = { type: 'string' };
const nulo = { type: ['string', 'null'] };

const schema = {
  type: 'object',
  properties: {
    clasificacion: { type: 'string', enum: ['solicitud', 'consulta', 'otro'] },
    empresa: nulo,
    ruc: nulo,
    contacto: nulo,
    email: nulo,
    telefono: nulo,
    necesidad: nulo,
    tipo_servicio: tipoServicio,
    productos: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          codigo: nulo,
          nombre: texto_,
          cantidad: { type: 'number' },
        },
        required: ['codigo', 'nombre', 'cantidad'],
        additionalProperties: false,
      },
    },
    urgencia: { type: 'string', enum: ['baja', 'media', 'alta'] },
    fecha_deseada: nulo,
    resumen: texto_,
  },
  required: ['clasificacion', 'empresa', 'ruc', 'contacto', 'email', 'telefono', 'necesidad', 'tipo_servicio', 'productos', 'urgencia', 'fecha_deseada', 'resumen'],
  additionalProperties: false,
};

return {
  json: {
    correo: {
      id: m.id,
      hilo: m.threadId || null,
      remitente_email: (remitente.address || '').toLowerCase(),
      remitente_nombre: remitente.name || null,
      asunto: m.subject || '',
      fecha: m.date || null,
      texto,
      html: m.html || null,
    },
    openai: {
      model: 'gpt-4o-mini',
      temperature: 0,
      messages: [
        { role: 'system', content: instruccion },
        { role: 'user', content: correo },
      ],
      response_format: {
        type: 'json_schema',
        json_schema: { name: 'analisis_correo', strict: true, schema },
      },
    },
  },
};

const correo = $('Preparar consulta').item.json.correo;
const texto = $json.choices?.[0]?.message?.content;
if (!texto) throw new Error(`OpenAI no devolvió datos para el correo ${correo.id}`);
const d = JSON.parse(texto);

const limpio = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);
const email = (limpio(d.email) || correo.remitente_email || '').toLowerCase() || null;
const fecha = /^\d{4}-\d{2}-\d{2}$/.test(d.fecha_deseada || '') ? d.fecha_deseada : null;

const productos = (Array.isArray(d.productos) ? d.productos : [])
  .map((p) => ({
    codigo: limpio(p.codigo),
    nombre: limpio(p.nombre) || limpio(p.codigo) || 'Producto sin nombre',
    cantidad: Number(p.cantidad) || 0,
  }))
  .filter((p) => p.cantidad > 0);

return {
  json: {
    correo,
    clasificacion: d.clasificacion || 'otro',
    empresa: limpio(d.empresa),
    ruc: (limpio(d.ruc) || '').replace(/\D/g, '') || null,
    contacto: limpio(d.contacto) || correo.remitente_nombre,
    email,
    telefono: limpio(d.telefono),
    necesidad: limpio(d.necesidad),
    tipo_servicio: limpio(d.tipo_servicio),
    productos,
    urgencia: ['baja', 'media', 'alta'].includes(d.urgencia) ? d.urgencia : 'baja',
    fecha_deseada: fecha,
    resumen: limpio(d.resumen) || '',
  },
};

const cfg = {
  url: $env.ODOO_URL,
  db: $env.ODOO_DB,
  user: $env.ODOO_USER,
  key: $env.ODOO_API_KEY,
  publicUrl: $env.ODOO_PUBLIC_URL || $env.ODOO_URL,
};
const rpc = async (service, method, args) => {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `${cfg.url}/jsonrpc`,
    json: true,
    body: { jsonrpc: '2.0', method: 'call', params: { service, method, args } },
  });
  if (res.error) throw new Error(`Odoo: ${res.error.data?.message || res.error.message}`);
  return res.result;
};
const uid = await rpc('common', 'login', [cfg.db, cfg.user, cfg.key]);
if (!uid) throw new Error('Odoo: usuario o API key incorrectos');
const odoo = (model, method, args, kwargs = {}) =>
  rpc('object', 'execute_kw', [cfg.db, uid, cfg.key, model, method, args, kwargs]);

const s = $json;

const previas = await odoo('crm.lead', 'search_read',
  [[['gmail_message_id', '=', s.correo.id]]],
  { fields: ['id', 'name'], limit: 1, context: { active_test: false } });
if (previas.length) {
  return { json: { ...s, duplicada: true, lead_id: previas[0].id, lead_nombre: previas[0].name } };
}

const [peru] = await odoo('res.country', 'search_read', [[['code', '=', 'PE']]], { fields: ['id'], limit: 1 });

let empresaId = false;
if (s.empresa || s.ruc) {
  const dominio = /^\d{11}$/.test(s.ruc || '')
    ? [['is_company', '=', true], '|', ['vat', '=', s.ruc], ['name', '=ilike', s.empresa || s.ruc]]
    : [['is_company', '=', true], ['name', '=ilike', s.empresa]];
  const [empresa] = await odoo('res.partner', 'search_read', [dominio], { fields: ['id'], limit: 1 });
  empresaId = empresa
    ? empresa.id
    : await odoo('res.partner', 'create', [{
        name: s.empresa || s.ruc,
        vat: /^\d{11}$/.test(s.ruc || '') ? s.ruc : false,
        is_company: true,
        customer_rank: 1,
        country_id: peru ? peru.id : false,
      }]);
}

let contactoId = false;
if (s.email) {
  const [existente] = await odoo('res.partner', 'search_read',
    [[['email', '=ilike', s.email], ['is_company', '=', false]]],
    { fields: ['id', 'parent_id'], limit: 1 });
  if (existente) {
    contactoId = existente.id;
    const cambios = {};
    if (empresaId && !existente.parent_id) cambios.parent_id = empresaId;
    if (s.telefono) cambios.phone = s.telefono;
    if (Object.keys(cambios).length) await odoo('res.partner', 'write', [[contactoId], cambios]);
  }
}
if (!contactoId && (s.contacto || s.email)) {
  contactoId = await odoo('res.partner', 'create', [{
    name: s.contacto || s.email,
    email: s.email || false,
    phone: s.telefono || false,
    parent_id: empresaId,
    type: 'contact',
    customer_rank: 1,
    country_id: peru ? peru.id : false,
  }]);
}

return {
  json: {
    ...s,
    duplicada: false,
    empresa_id: empresaId || null,
    contacto_id: contactoId || null,
    partner_id: contactoId || empresaId || null,
  },
};

const cfg = {
  url: $env.ODOO_URL,
  db: $env.ODOO_DB,
  user: $env.ODOO_USER,
  key: $env.ODOO_API_KEY,
  publicUrl: $env.ODOO_PUBLIC_URL || $env.ODOO_URL,
};
const rpc = async (service, method, args) => {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `${cfg.url}/jsonrpc`,
    json: true,
    body: { jsonrpc: '2.0', method: 'call', params: { service, method, args } },
  });
  if (res.error) throw new Error(`Odoo: ${res.error.data?.message || res.error.message}`);
  return res.result;
};
const uid = await rpc('common', 'login', [cfg.db, cfg.user, cfg.key]);
if (!uid) throw new Error('Odoo: usuario o API key incorrectos');
const odoo = (model, method, args, kwargs = {}) =>
  rpc('object', 'execute_kw', [cfg.db, uid, cfg.key, model, method, args, kwargs]);

const s = $json;
const html = (t) => String(t || '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/\n/g, '<br/>');

let tipo = null;
if (s.tipo_servicio) {
  [tipo] = await odoo('crm.service.type', 'search_read',
    [[['code', '=', s.tipo_servicio]]], { fields: ['id', 'name'], limit: 1 });
}

const lineas = [];
const faltantes = [];
for (const p of s.productos) {
  let [producto] = p.codigo
    ? await odoo('product.product', 'search_read',
        [[['default_code', '=ilike', p.codigo], ['sale_ok', '=', true]]],
        { fields: ['id', 'display_name', 'qty_available', 'uom_id'], limit: 1 })
    : [];
  if (!producto) {
    [producto] = await odoo('product.product', 'search_read',
      [[['name', 'ilike', p.nombre], ['sale_ok', '=', true]]],
      { fields: ['id', 'display_name', 'qty_available', 'uom_id'], limit: 1 });
  }
  if (!producto) {
    faltantes.push({ producto: p.nombre, cantidad: p.cantidad, disponible: 0, motivo: 'no registrado' });
    continue;
  }
  lineas.push({ producto_id: producto.id, producto: producto.display_name, cantidad: p.cantidad });
  if (producto.qty_available < p.cantidad) {
    faltantes.push({ producto: producto.display_name, cantidad: p.cantidad, disponible: producto.qty_available, motivo: 'stock insuficiente' });
  }
}

const sinStock = faltantes.length > 0;
const etiquetas = [];
if (sinStock) {
  const [etiqueta] = await odoo('crm.tag', 'search_read', [[['name', '=', 'Sin stock']]], { fields: ['id'], limit: 1 });
  etiquetas.push(etiqueta ? etiqueta.id : await odoo('crm.tag', 'create', [{ name: 'Sin stock', color: 1 }]));
}

const cliente = s.empresa || s.contacto || s.email;
const titulo = s.correo.asunto ? s.correo.asunto.replace(/^((re|rv|fw|fwd)\s*:\s*)+/i, '') : (tipo?.name || 'Solicitud');
const detalle = s.productos.map((p) => `${p.cantidad} x ${p.nombre}${p.codigo ? ` (${p.codigo})` : ''}`).join('\n');

const leadId = await odoo('crm.lead', 'create', [{
  type: 'opportunity',
  name: `${cliente}: ${titulo}`.slice(0, 200),
  partner_id: s.partner_id || false,
  partner_name: s.empresa || false,
  contact_name: s.contacto || false,
  email_from: s.email || false,
  phone: s.telefono || false,
  description: s.necesidad ? `<p>${html(s.necesidad)}</p>` : false,
  request_origin: 'email',
  urgency: s.urgencia,
  priority: { alta: '2', media: '1', baja: '0' }[s.urgencia],
  service_type_id: tipo ? tipo.id : false,
  desired_date: s.fecha_deseada || false,
  date_deadline: s.fecha_deseada || false,
  ai_summary: s.resumen || false,
  requested_items: detalle || false,
  gmail_message_id: s.correo.id,
  tag_ids: [[6, 0, etiquetas]],
}]);

const adjuntos = [];
if (s.correo.html) {
  adjuntos.push(await odoo('ir.attachment', 'create', [{
    name: 'Correo original.html',
    datas: Buffer.from(s.correo.html, 'utf8').toString('base64'),
    mimetype: 'text/html',
    res_model: 'crm.lead',
    res_id: leadId,
  }]));
}

await odoo('crm.lead', 'message_post', [[leadId]], {
  body: `<p><b>De:</b> ${html(s.correo.remitente_nombre || '')} &lt;${html(s.correo.remitente_email)}&gt;<br/>`
    + `<b>Asunto:</b> ${html(s.correo.asunto)}<br/><b>Fecha:</b> ${html(s.correo.fecha || '')}</p>`
    + `<p>${html(s.correo.texto)}</p>`,
  body_is_html: true,
  attachment_ids: adjuntos,
  message_type: 'comment',
  subtype_xmlid: 'mail.mt_note',
});

let pedido = null;
if (lineas.length && s.partner_id) {
  const pedidoId = await odoo('sale.order', 'create', [{
    partner_id: s.partner_id,
    opportunity_id: leadId,
    origin: `Correo ${s.correo.id}`,
    order_line: [
      ...lineas.map((l) => [0, 0, { product_id: l.producto_id, product_uom_qty: l.cantidad }]),
      ...faltantes.filter((f) => f.motivo === 'no registrado').map((f) => [0, 0, {
        display_type: 'line_note',
        name: `Producto no registrado: ${f.cantidad} x ${f.producto}`,
      }]),
    ],
  }]);
  [pedido] = await odoo('sale.order', 'read', [[pedidoId]], { fields: ['name', 'amount_total', 'currency_id'] });
}

if (sinStock) {
  await odoo('crm.lead', 'message_post', [[leadId]], {
    body: `Faltantes de stock: ${faltantes.map((f) => f.motivo === 'no registrado'
      ? `${f.producto} (${f.cantidad}, no registrado)`
      : `${f.producto} (pide ${f.cantidad}, disponible ${f.disponible})`).join('; ')}.`,
    message_type: 'comment',
    subtype_xmlid: 'mail.mt_note',
  });
}

return {
  json: {
    lead_id: leadId,
    cliente,
    titulo,
    urgencia: s.urgencia,
    tipo_servicio: tipo?.name || null,
    cotizacion: pedido?.name || null,
    cotizacion_id: pedido?.id || null,
    total: pedido?.amount_total ?? null,
    sin_stock: sinStock,
    faltantes,
    faltantes_texto: faltantes
      .map((f) => f.motivo === 'no registrado'
        ? `• ${f.producto}: ${f.cantidad}, no registrado en Odoo`
        : `• ${f.producto}: pide ${f.cantidad}, disponible ${f.disponible}`)
      .join('\n'),
    enlace: `${cfg.publicUrl}/odoo/action-crm.crm_lead_action_pipeline/${leadId}`,
  },
};

